import os,re
mods=set()
for r,d,fs in os.walk('AlgebraicJacobian'):
    for f in fs:
        if f.endswith('.lean'):
            p=os.path.join(r,f)[:-5].replace('/','.')
            mods.add(p)
# transitive closure from AlgebraicJacobian.lean
imports={}
def imps(m):
    p=m.replace('.','/')+'.lean'
    if not os.path.exists(p): return set()
    return set(re.findall(r'^import\s+(AlgebraicJacobian[\w.]*)',open(p).read(),re.M))
seen=set()
stack=list(imps('AlgebraicJacobian'))
while stack:
    m=stack.pop()
    if m in seen: continue
    seen.add(m)
    stack+= [x for x in imps(m) if x not in seen]
print('modules on disk:',len(mods))
print('reachable from root:',len(seen&mods))
print('UNROOTED:',sorted(mods-seen))
EOF
